"""File for housing all agnostic functions that manage AUT contexts and retrieving data pretaining to AUTs
running in a active squish runner instance"""

import squishtest

class NoAppHandleInContextListError(Exception):
    """
    Thrown when an AUT doesn't appear in a Squish Application Context List
    """
    def __init__(self, appContextList, autName) -> None:
        if len(appContextList) == 0:
            message = f"""There are no AUTs currently active in the squish context"""
        else:
            message = f"""No AUT with name: {autName} was found in the active context list"""
        super().__init__(message)

def is_aut_running(autName: str) -> bool:
    """Checks to see if a given autName is running in the current Squish test context.

    :param str autName: Name of AUT that would apear in the ContextList
    :return: True or False
    :rtype: bool
    """
    apps = squishtest.applicationContextList() #type: ignore
    if (autName not in str(apps)):
        return False
    return True

def set_app_context(autName: str) -> None:
    """Gets the current list of active AUT contexts and then sets the context to the AUT handle of the given AUT name

    :param str autName: Name of the AUT that will become the active context
    """
    apps = squishtest.applicationContextList() #type: ignore
    try:
        app_handle = next(handle for handle in apps if handle.name == autName and len(apps) != 0)
        squishtest.setApplicationContext(app_handle) #type: ignore

    except StopIteration:
        raise NoAppHandleInContextListError(apps, autName)

def get_current_app_context():
    """Returns the context handle of the current AUT context of the squish runner."""
    return squishtest.currentApplicationContext() #type: ignore

def get_aut_name_of_current_context() -> str:
    """Returns as a str, the name of the current AUT context of the squish runner.

    :rtype: str
    """
    return str(squishtest.currentApplicationContext()) #type: ignore

def get_aut_pid(autName: str) -> int:
    """Returns as a int, the PID number of a running AUT context matching the given AUT name.

    :param str autName: Name of the AUT who's PID number is returned
    :rtype: int
    """
    apps = squishtest.applicationContextList() #type: ignore
    try:
        app_handle = next(handle for handle in apps if handle.name == autName)
        return app_handle.pid

    except StopIteration:
        raise NoAppHandleInContextListError(apps, autName)

def wait_for_application_launch():
    """Returns the new context of another AUT of the squish runner."""
    return squishtest.waitForApplicationLaunch() #type: ignore
